package com.aistock.prediction.portfolioanalysis;
import com.aistock.prediction.marketuse.*;import com.aistock.prediction.modelcatalog.ModelRecords.Actor;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import java.math.BigDecimal;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static com.aistock.prediction.portfolioanalysis.PortfolioRecords.*;import static com.aistock.prediction.portfolioanalysis.PortfolioTestEvidence.*;
@Tag("mysql") class PortfolioUseMysqlTest {
 PortfolioRepositoryMysqlTest db;PortfolioRepository repo;PortfolioMarketUseOwner uses;MarketUseClient client;PortfolioSources sources;PortfolioService svc;AtomicReference<Instant> now;Clock clock;UUID request;SessionToken token=new SessionToken("a".repeat(43));Actor actor=new Actor(OWNER,"USER");
 @BeforeEach void setup(){db=new PortfolioRepositoryMysqlTest();db.setup();repo=db.repo;request=UUID.randomUUID();now=new AtomicReference<>(NOW);clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return now.get();}};client=mock(MarketUseClient.class);when(client.register(any())).thenAnswer(c->receipt());when(client.complete(any(),any())).thenAnswer(c->{var b=(MarketUseClient.Receipt)c.getArgument(1);return new MarketUseClient.Receipt(b.bundleId(),"RELEASED",b.versionIds());});uses=new PortfolioMarketUseOwner(db.jdbc,db.mapper,repo,client,clock,true);sources=mock(PortfolioSources.class);when(sources.snapshot(token)).thenReturn(normal());when(sources.revision(token)).thenReturn(new PositionRevision(OWNER,"stock-user-service","2"));when(sources.quotes(anyList(),any())).thenAnswer(c->new QuoteBatch(c.getArgument(1),NOW,prices().items()));svc=new PortfolioService(repo,sources,clock,new BigDecimal("50"),1,uses);}
 MarketUseClient.Receipt receipt(){return new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",prices().items().stream().map(q->q.versionId().toString()).sorted().toList());}
 UUID execution(){return UUID.fromString(db.jdbc.queryForObject("select execution_id from portfolio_market_use",String.class));}
 @Test void nonemptyValuationUsesFullSetAndNotifiesOnlyAfterCommittedResult(){when(sources.quotes(anyList(),any())).thenAnswer(c->{assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());assertEquals("PORTFOLIO_VALUATION",MarketUseContext.headers().get("X-Market-Use-Purpose"));assertEquals(2,MarketUseContext.expectedVersions().size());return new QuoteBatch(c.getArgument(1),NOW,prices().items());});doAnswer(c->{assertTrue(MarketUseContext.headers().isEmpty());assertEquals(1,db.jdbc.queryForObject("select count(*) from portfolio_analysis_result",Integer.class));var b=(MarketUseClient.Receipt)c.getArgument(1);return new MarketUseClient.Receipt(b.bundleId(),"RELEASED",b.versionIds());}).when(client).complete(any(),any());var done=svc.create(actor,token,new Request(request)).operation();assertEquals("SUCCEEDED",done.state());var proof=uses.proof(execution(),"1");assertEquals(9,proof.size());assertEquals(done.analysisId().toString(),proof.path("resultIdentity").asText());var saved=repo.get(OWNER,done.analysisId()).toString();assertTrue(svc.create(actor,token,new Request(request)).replayed());assertEquals(saved,repo.get(OWNER,done.analysisId()).toString());verify(sources,times(1)).quotes(anyList(),any());verify(client,times(1)).register(any());var payload=db.jdbc.queryForObject("select selector_json from portfolio_market_use",String.class);assertFalse(payload.contains("quantity"));assertFalse(payload.contains("averageCost"));assertFalse(payload.contains(token.value()));}
 @Test void emptyBookNeverRegistersButStillSavesAndChecksRevision(){when(sources.snapshot(token)).thenReturn(snapshot());assertEquals("SUCCEEDED",svc.create(actor,token,new Request(request)).operation().state());verifyNoInteractions(client);verify(sources,never()).quotes(anyList(),any());verify(sources).revision(token);assertEquals(0,db.jdbc.queryForObject("select count(*) from portfolio_market_use",Integer.class));}
 @Test void deniedOrWrongRawManifestCannotSave(){for(boolean denied:List.of(true,false)){if(denied)doThrow(MarketUseClient.notReady()).when(client).requireReady();else{doNothing().when(client).requireReady();doReturn(new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(UUID.randomUUID().toString(),UUID.randomUUID().toString()))).when(client).register(any());}var req=UUID.randomUUID();assertThrows(com.aistock.common.BusinessException.class,()->svc.create(actor,token,new Request(req)));assertEquals("FAILED",repo.operation(OWNER,req,NOW).state());assertEquals(0,db.jdbc.queryForObject("select count(*) from portfolio_analysis_result",Integer.class));}verify(sources,times(1)).quotes(anyList(),any());assertTrue(MarketUseContext.headers().isEmpty());}
 @Test void proofExpiresPhysicallyAndClockRollbackCannotReviveWorker(){var c=repo.claim(OWNER,request,NOW,DATE,new BigDecimal("50"));try(var scope=uses.acquire(OWNER,request,c.generation(),List.of("SH600276","SH600030"))){}assertThrows(RuntimeException.class,()->uses.proof(c.generation(),"1"));now.set(NOW.plusSeconds(31));var p=uses.proof(c.generation(),"1");assertEquals("FAILED",p.path("state").asText());now.set(NOW);assertThrows(RuntimeException.class,()->repo.complete(OWNER,request,c.generation(),calculation(),normal(),prices(),clock));assertEquals(p,uses.proof(c.generation(),"1"));assertFalse(repo.claim(OWNER,request,NOW,DATE,new BigDecimal("50")).execute());assertThrows(RuntimeException.class,()->uses.proof(c.generation(),"2"));}
 @Test void unknownRegistrationRestartsWithOriginalIdWithoutTokenOrAnotherPost(){doThrow(MarketUseClient.unavailable()).when(client).register(any());assertThrows(RuntimeException.class,()->svc.create(actor,token,new Request(request)));var cap=org.mockito.ArgumentCaptor.forClass(MarketUseClient.Request.class);verify(client).register(cap.capture());var r=cap.getValue();when(client.find(r)).thenReturn(Optional.of(receipt()));var recovered=new PortfolioMarketUseOwner(db.jdbc,db.mapper,repo,client,clock,true);recovered.recoverOne(UUID.fromString(r.operationId()));verify(client,times(1)).register(any());verify(client).find(r);verify(sources,never()).quotes(anyList(),any());verify(sources,never()).revision(any());assertTrue(db.jdbc.queryForObject("select completion_acked from portfolio_market_use",Boolean.class));assertEquals("FAILED",recovered.proof(UUID.fromString(r.operationId()),"1").path("state").asText());}
 @Test void proofRereadsClockAfterActualOwnerRowLockWait()throws Exception{var c=repo.claim(OWNER,request,NOW,DATE,new BigDecimal("50"));try(var scope=uses.acquire(OWNER,request,c.generation(),List.of("SH600030","SH600276"))){}var pool=Executors.newSingleThreadExecutor();try(var lock=db.jdbc.getDataSource().getConnection()){lock.setAutoCommit(false);try(var q=lock.prepareStatement("select owner_id from portfolio_analysis_operation where owner_id=? and request_id=? for update")){q.setString(1,OWNER.toString());q.setString(2,request.toString());q.executeQuery().close();}var proof=pool.submit(()->uses.proof(c.generation(),"1"));long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);boolean waiting=false;while(System.nanoTime()<end){if(db.jdbc.queryForObject("select count(*) from performance_schema.data_lock_waits",Integer.class)>0){waiting=true;break;}Thread.sleep(10);}assertTrue(waiting);now.set(NOW.plusSeconds(31));lock.commit();assertEquals("FAILED",proof.get(4,TimeUnit.SECONDS).path("state").asText());assertEquals("FAILED",repo.operation(OWNER,request,NOW).state());}finally{pool.shutdownNow();}}

}
